function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // broken pieces
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.sin(t), H/2);
  ctx.lineTo(W/2 + 20*Math.cos(t), H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 20*Math.sin(t), H/2);
  ctx.lineTo(W/2 - 20*Math.cos(t), H/2 + 50);
  ctx.stroke();

  // slowly rebuilding
  let rebuildProgress = Math.sin(t) * 0.5 + 0.5;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 30*rebuildProgress, 0, 2*Math.PI);
  ctx.stroke();

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 40);
  ctx.lineTo(W/2 - 20, H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 40);
  ctx.lineTo(W/2 + 20, H/2 - 10);
  ctx.stroke();

  ctx.restore();
}
